mkdir -p /tmp/sms-gate-test && cat > /tmp/sms-gate-test/test.mjs <<'EOF'
import assert from "node:assert/strict";
import { checkSms } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-inv-g1-1/bot.mjs";

const PROMO = "Sale! 20% off jackets this weekend. Reply STOP to opt out.";
const base = (over = {}) => ({
  kind: "marketing",
  body: PROMO,
  to: { phone: "+13125550142", timeZone: "America/Chicago", marketingConsent: true, optedOutAt: null, ...over.to },
  ...Object.fromEntries(Object.entries(over).filter(([k]) => k !== "to")),
});
// 2026-10-22 local times in Chicago (CDT, UTC-5) -> UTC
const at = (utcIso) => new Date(utcIso);
const chicago12pm = at("2026-10-22T17:00:00Z"); // 12:00 CDT
const chicago750am = at("2026-10-22T12:50:00Z"); // 07:50 CDT
const chicago8am = at("2026-10-22T13:00:00Z");   // 08:00 CDT
const chicago855pm = at("2026-10-23T02:55:00Z"); // 21:55 CDT Oct 22
const chicago9pm = at("2026-10-23T02:00:00Z");   // 21:00 CDT Oct 22
const chicago859pm = at("2026-10-23T01:59:00Z"); // 20:59 CDT Oct 22
const midnight = at("2026-10-22T05:00:00Z");     // 00:00 CDT

const cases = [
  ["marketing ok midday", base(), chicago12pm, { allowed: true, reason: null }],
  ["quiet before 8", base(), chicago750am, { allowed: false, reason: "outside_quiet_hours" }],
  ["8:00 allowed", base(), chicago8am, { allowed: true, reason: null }],
  ["20:59 allowed", base(), chicago859pm, { allowed: true, reason: null }],
  ["21:00 blocked", base(), chicago9pm, { allowed: false, reason: "outside_quiet_hours" }],
  ["midnight blocked", base(), midnight, { allowed: false, reason: "outside_quiet_hours" }],
  ["no consent", base({ to: { marketingConsent: false } }), chicago12pm, { allowed: false, reason: "no_marketing_consent" }],
  ["consent missing", base({ to: { marketingConsent: undefined } }), chicago12pm, { allowed: false, reason: "no_marketing_consent" }],
  ["opted out marketing", base({ to: { optedOutAt: "2026-10-01T10:00:00Z" } }), chicago12pm, { allowed: false, reason: "opted_out" }],
  ["bad optedOutAt", base({ to: { optedOutAt: "not a date" } }), chicago12pm, { allowed: false, reason: "invalid_opt_out_timestamp" }],
  ["bad timezone", base({ to: { timeZone: "Mars/Olympus" } }), chicago12pm, { allowed: false, reason: "invalid_time_zone" }],
  ["no STOP text", base({ body: "Sale! 20% off jackets this weekend." }), chicago12pm, { allowed: false, reason: "missing_opt_out_instructions" }],
  ["bad phone", base({ to: { phone: "3125550142" } }), chicago12pm, { allowed: false, reason: "invalid_phone_number" }],
  ["UK phone", base({ to: { phone: "+447700900123" } }), chicago12pm, { allowed: false, reason: "invalid_phone_number" }],
  ["empty body", base({ body: "   " }), chicago12pm, { allowed: false, reason: "empty_body" }],
  ["bad kind", base({ kind: "promo" }), chicago12pm, { allowed: false, reason: "invalid_kind" }],
  ["transactional login code", { kind: "transactional", body: "Your login code is 445892. Valid 10 minutes.", to: { phone: "+13125550142", timeZone: "America/Chicago", marketingConsent: false, optedOutAt: null } }, midnight, { allowed: true, reason: null }],
  ["transactional at night allowed", { kind: "transactional", body: "Your order shipped.", to: { phone: "+13125550142", timeZone: "America/Chicago", marketingConsent: false, optedOutAt: null } }, midnight, { allowed: true, reason: null }],
  ["transactional with promo", { kind: "transactional", body: "Your order shipped. Here's 15% off your next order.", to: { phone: "+13125550142", timeZone: "America/Chicago", marketingConsent: false, optedOutAt: null } }, chicago12pm, { allowed: false, reason: "transactional_contains_marketing" }],
  ["opted out transactional", { kind: "transactional", body: "Your code is 445892.", to: { phone: "+13125550142", timeZone: "America/Chicago", marketingConsent: false, optedOutAt: "2026-10-01T10:00:00Z" } }, chicago12pm, { allowed: false, reason: "opted_out" }],
];

let fail = 0;
for (const [name, msg, now, want] of cases) {
  try { assert.deepStrictEqual(checkSms(msg, now), want); console.log("ok  ", name); }
  catch (e) { fail++; console.log("FAIL", name, JSON.stringify(checkSms(msg, now)), "want", JSON.stringify(want)); }
}

// Server time zone must not matter: same instant, different TZ env, same answer.
for (const tz of ["UTC", "Asia/Tokyo", "America/Los_Angeles"]) {
  process.env.TZ = tz;
  const r = checkSms(base(), chicago750am);
  assert.equal(r.reason, "outside_quiet_hours", `server TZ ${tz}`);
}
console.log("ok   server TZ independence");
console.log(fail ? `${fail} FAILED` : "all passed");
process.exitCode = fail ? 1 : 0;
EOF
cd /tmp/sms-gate-test && node -v && node test.mjs
